    -- BP scenario 1: cfg01 — m_tready(0) stalled 10 cycles post-reset (Phase 3 regression)
    p_bp01 : process
    begin
        c01_mready(0) <= '0';
        c01_mready(C01_NUM_TAPS-1 downto 1) <= (others => '1');
        wait until c01_rst = '0';
        wait for CLK_PERIOD * 10;
        c01_mready(0) <= '1';
        wait;
    end process p_bp01;

    -- BP scenario 2: cfg55 (7x7 ZERO FLUSH=off) — m_tready(NUM_TAPS-1) stalled 10 cycles
    -- Verifies that back-pressure on the LAST tap port stalls the pipeline correctly.
    p_bp55 : process
    begin
        c55_mready(C55_NUM_TAPS-1) <= '0';
        c55_mready(C55_NUM_TAPS-2 downto 0) <= (others => '1');
        wait until c55_rst = '0';
        wait for CLK_PERIOD * 10;
        c55_mready(C55_NUM_TAPS-1) <= '1';
        wait;
    end process p_bp55;

    -- BP scenario 3: cfg40 (3x3 ZERO FLUSH=on, LW=16 FH=4) — m_tready(0) stalled mid-flush.
    -- Real stimulus ends ~cycle 197; deassert at cycle 210, hold 15 cycles into flush phase.
    p_bp40 : process
    begin
        wait until c40_rst = '0';
        wait for CLK_PERIOD * 210;
        c40_mready(0) <= '0';
        wait for CLK_PERIOD * 15;
        c40_mready(0) <= '1';
        wait;
    end process p_bp40;

    -- Stimulus processes

    p_stim01 : process
        file     f   : text;
        variable ln  : line;
        variable pv  : integer;
        variable col : natural range 0 to 8-1;
        variable row : natural range 0 to 8-1;
    begin
        wait for CLK_PERIOD * 5;
        wait until rising_edge(clk);
        c01_rst <= '0';
        file_open(f, C01_IN_FILE, read_mode);
        col := 0;  row := 0;
        while not endfile(f) loop
            readline(f, ln);  read(ln, pv);
            c01_sdata  <= std_logic_vector(to_unsigned(pv, C01_DW));
            c01_svalid <= '1';
            if row = 0 and col = 0 then c01_suser <= '1'; else c01_suser <= '0'; end if;
            if col = 8-1 then c01_slast <= '1'; else c01_slast <= '0'; end if;
            wait until rising_edge(clk) and c01_sready = '1';
            if col = 8-1 then
                col := 0;
                if row = 8-1 then row := 0; else row := row+1; end if;
            else
                col := col+1;
            end if;
        end loop;
        c01_svalid <= '0';  c01_slast <= '0';  c01_suser <= '0';
        file_close(f);
        wait;
    end process p_stim01;

