    -- Checker processes

    p_check01 : process
        file     f         : text;
        variable ln        : line;
        variable tv        : integer;
        variable exp_vec   : std_logic_vector(8*9-1 downto 0);
        variable out_count : natural := 0;
        variable err_count : natural := 0;
    begin
        wait until c01_rst = '0';
        file_open(f, C01_EXP_FILE, read_mode);
        while not endfile(f) loop
            wait until rising_edge(clk) and c01_mvalid = '1' and c01_mready = ((c01_mready'range) => '1');
            readline(f, ln);
            for tap in 0 to 9-1 loop
                read(ln, tv);
                exp_vec((tap+1)*8-1 downto tap*8)
                    := std_logic_vector(to_unsigned(tv, 8));
            end loop;
            if c01_mdata /= exp_vec then
                report "CFG01 MISMATCH at output " & integer'image(out_count)
                    severity error;
                err_count := err_count+1;
            end if;
            out_count := out_count+1;
        end loop;
        file_close(f);
        if err_count = 0 then
            report "CFG01 PASS (8b 3x3 ZERO FLUSH=off 8x8frame): " & integer'image(out_count)
                & " outputs checked." severity note;
        else
            report "CFG01 FAIL (8b 3x3 ZERO FLUSH=off 8x8frame): " & integer'image(err_count)
                & " mismatches in " & integer'image(out_count)
                & " outputs." severity failure;
        end if;
        done_flags(0) <= '1';
        wait;
    end process p_check01;

    p_check02 : process
        file     f         : text;
        variable ln        : line;
